"""Takes in a a list of lists, which include the pairs and the third element of each list is L.O.S.

    Args:
        list_pairs (list of lists): First element is crypto pair 1, second element crypto pair 2 and third element is L.O.S.
    """
def identify_significant_pairs(list_pairs: Any) -> object {
    return [
        x
        for x in list_pairs
        if (x[2] <= 0.05)
    ];
}

"""Split and read pdb-file line (QPREP-OUT).

     Extract and return:
        atomnumber, atomname, resname, resid)
    """
def get_pdb_atom_info(line: Any) -> object {
    atomnum = int(line[6:11]);
    atmname = line[13:17].strip();
    resname = line[17:20].strip();
    resinum = int(line[22:27]);
    return (atomnum, atmname, resname, resinum);
}

"""
    Returns the Number of minimum stocks per sector requiered to get to the nr_of_stocks with the selected sectors

    Args:
        nr_of_stocks (ind): Readout of the 'nr_of_stocks' input in the interface.
        sectors (list): List that is returned from the 'sectors' selectionbox in the interface

    Returns:
        mss (int): Number of minimum stocks per sector
        10 (int): If no sectors are selected it returns 10 as a default argument.
    """
def get_min_sec_stocks(nr_of_stocks: Any, sectors: Any) -> object {
    try {
        mss = int(round(((nr_of_stocks / len(sectors)) + 0.5)));
        return mss;
    } except ZeroDivisionError {
        return 10;
    }
}

"""Validate inputted json data

    This function tests 3 criteria for the inputted json file.
    1. It must be a dictionary
    2. It must contain all of the expected_keys: "patient_id" and
    "heart_rate"
    3. It must contain the correct data types for each key. All values must be
       integers or integers in a string format.
   The appropriate error message will be returned based on what the json file
   is missing or has incorrect.
   If the json file has the correct format and data types, the function will
   return True, 200 as a passing boolean and status_code.
   This function will also validate any integers that have been entered as a
   string data type.

   :param in_heart_rate: This is a dictionary from the inputted json file
   :param heart_rate_expected_keys: This is a dictionary containing keys for
   "patient_id" and "heart_rate". The value of each key is the expected data
   type (int).

   :returns: This function returns either an error string and an error code
   describing the validation error, or True, 200 if no errors occurred.
   """
def validate_heart_rate_timestamp(
    in_heart_rate: Any, heart_rate_expected_keys: Any
) -> object {
    if (`type(in_heart_rate) is not `dict) {
        return ("The input was not a dictionary", 400);
    }
    for key in heart_rate_expected_keys {
        if (key not in in_heart_rate) {
            return ("The key {} is missing from input".format(key), 400);
        }
        if (`type(in_heart_rate[key]) is not heart_rate_expected_keys[key]) {
            try {
                in_heart_rate[key] = int(in_heart_rate[key]);
            } except ValueError {
                return ("The key {} has the wrong data type".format(key), 400);
            }
        }
    }
    return (True, 200);
}

"""Does given bytes object end with the subsequence suffix?

    Compiling bytes.endswith, with no range arguments, compiles this function.
    This function is only intended to be executed in this compiled form.

    Args:
        x: The bytes object to examine.
        suffix: The subsequence to look for.

    Returns:
        Result of check.
    """
def bytes_endswith(x: bytes, suffix: bytes) -> bool {
    index = len(x) - len(suffix);
    if (index < 0) {
        return False;
    }
    for i in suffix {
        if (x[index] != i) {
            return False;
        }
        index += 1;
    }
    return True;
}
